.screen{inset:0;display:grid;place-items:center}.screen[hidden],.hud[hidden],.duel-prompt[hidden]{display:none}.intro-screen{pointer-events:none}.intro-copy{position:absolute;left:11.5%;top:50%;transform:translateY(-46%);pointer-events:auto}.intro-copy .eyebrow{display:flex;align-items:center;gap:10px;font-size:9px;letter-spacing:2.5px}.eyebrow-rule{width:24px;height:1px;background:var(--gold)}h1{font:600 clamp(56px,8.6vw,112px)/.87 var(--display);letter-spacing:3px;margin:22px 0 18px;text-shadow:0 6px 24px rgba(27,12,8,.35)}h1 em,.ending-card h2 em{font:italic 600 .77em var(--serif);letter-spacing:0;color:var(--gold)}.intro-desc{font:14px/1.8 var(--serif);color:#e8cbb0;margin:0 0 28px}.action-button{height:54px;min-width:255px;padding:0 18px;display:flex;align-items:center;justify-content:space-between;gap:35px;background:var(--gold);border:1px solid #f4c679;color:#231610;font:500 11px var(--mono);letter-spacing:1.2px;cursor:pointer;transition:background .2s,transform .2s,box-shadow .2s;pointer-events:auto}.action-button b{font:20px var(--display)}.action-button:hover{background:#f1c57e;transform:translateY(-2px);box-shadow:0 7px 25px #21100b55}.controls-note{color:rgba(255,235,208,.72);font:9px var(--mono);letter-spacing:1px;margin:19px 0}.controls-note span{color:var(--gold);font-size:16px;vertical-align:-2px;margin-right:6px}kbd{border:1px solid #f2d3ab77;padding:3px 6px;border-radius:2px;color:var(--ink);font:9px var(--mono);margin-left:5px}.intro-stamp{position:absolute;right:13%;top:40%;width:156px;height:156px;border:1px solid #f1d2aa99;border-radius:50%;transform:rotate(12deg);display:flex;flex-direction:column;justify-content:center;align-items:center;color:#f5d6b1;text-align:center;text-shadow:0 2px 6px #382018;font-family:var(--display);opacity:.84}.intro-stamp:before,.intro-stamp:after{content:"";position:absolute;inset:6px;border:1px solid #f1d2aa77;border-radius:50%}.intro-stamp span{font-size:9px;letter-spacing:2px}.intro-stamp strong{font-size:27px;line-height:.95;letter-spacing:1px;margin:6px}.intro-stamp b{font:9px var(--mono);letter-spacing:1px;margin-top:6px}.bottom-caption{position:absolute;left:5.2%;right:5.2%;bottom:108px;display:flex;justify-content:space-between;color:#efcfab;font-size:9px;letter-spacing:1.5px}
.duel-prompt{left:50%;top:31%;transform:translate(-50%,-50%);text-align:center;min-width:300px;text-shadow:0 3px 14px #20100c}.prompt-kicker,.prompt-sub{display:block;color:#f5d6b1;font-size:10px;letter-spacing:2px}.prompt-text{display:block;font:600 clamp(36px,6.6vw,75px)/1 var(--display);letter-spacing:3px;color:#fff0d9;margin:6px 0}.prompt-sub{font-size:9px;color:#eed1b0;letter-spacing:1.5px}.duel-prompt.ready .prompt-text{color:#ffd47e;text-shadow:0 0 25px #ff8e4266,0 3px 14px #20100c}.duel-prompt.ready .prompt-kicker{color:#ffd47e}
.bottom-ui{left:5.2%;right:5.2%;bottom:27px;display:flex;align-items:flex-end;justify-content:space-between}.duel-progress{display:flex;gap:8px;align-items:center}.progress-dot{width:29px;height:3px;background:#ffe5c344;transition:background .3s,box-shadow .3s}.progress-dot.active{background:#f2c276;box-shadow:0 0 9px #f2c27677}.progress-dot.done{background:#ecc07a}.bottom-hint,.edition{color:#f2d8bc;font-size:9px;letter-spacing:1.3px}.bottom-hint span{color:var(--gold);padding:0 5px}.edition b{color:var(--gold);margin-left:8px}.mobile-controls{display:none}.result-screen,.ending-screen{background:rgba(21,13,11,.42);backdrop-filter:blur(2px)}.result-card,.ending-card{width:min(440px,90vw);padding:34px 40px;background:rgba(30,18,14,.91);border:1px solid #dfb77966;text-align:center;box-shadow:0 20px 70px #10090577;animation:cardin .45s ease both}.result-card:before,.ending-card:before{content:"✦";display:block;color:var(--gold);font-size:19px;margin-bottom:12px}@keyframes cardin{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}.result-card .eyebrow,.ending-card .eyebrow{font-size:9px}.result-card h2,.ending-card h2{font:600 51px/.96 var(--display);margin:13px 0 6px;letter-spacing:1.5px}.result-card>p:not(.eyebrow),.ending-card>p:not(.eyebrow){color:#dfc4a6;font:14px/1.7 var(--serif);margin:10px 0 21px}.result-stats,.final-score{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #e8c79b33;padding:13px 0 17px;color:#d4b99a;font-size:9px;letter-spacing:1.1px}.result-stats strong,.final-score strong{color:var(--gold);font:18px var(--display)}.result-card .action-button,.ending-card .action-button{width:100%;height:49px}.ending-card h2{font-size:61px}.ending-card h2 em{font-size:.8em}.ending-card{width:min(420px,90vw)}.flash{position:absolute;inset:0;background:#fff2d6;opacity:0;pointer-events:none;z-index:8}.flash.fire{animation:flash .28s ease-out}@keyframes flash{0%{opacity:.82}100%{opacity:0}}.toast{left:50%;top:63%;transform:translate(-50%,-50%);padding:10px 16px;background:#261713e8;border:1px solid #d59b5b;color:#f4d0a6;font-size:10px;letter-spacing:1.6px;white-space:nowrap;opacity:0;transition:opacity .2s;pointer-events:none}.toast.show{opacity:1}
@media(max-width:700px){.game-shell{min-height:100dvh}.topbar{top:max(18px,env(safe-area-inset-top));left:6%;right:6%}.brand{font-size:13px;gap:8px;letter-spacing:1.7px}.brand-mark{font-size:18px}.top-meta{gap:10px;font-size:8px}.chapter{letter-spacing:1px}.sound-button{font-size:0}.sound-button:first-letter{font-size:15px}.sound-button span{display:none}.hud{top:75px;left:6%;right:6%;gap:15px}.round-label strong{font-size:23px}.round-name{font-size:8px;letter-spacing:.5px}.round-line{width:23px}.opponent-label{font-size:7px}.opponent-card strong,.score-card strong{font-size:15px}.score-card{margin-left:0}.opponent-rank{font-size:8px}.intro-copy{left:8%;top:48%;transform:translateY(-40%)}.intro-copy .eyebrow{font-size:8px;letter-spacing:1.6px}h1{font-size:clamp(62px,17vw,95px);margin:19px 0 14px}.intro-desc{font-size:13px}.action-button{min-width:238px;height:51px;font-size:10px}.intro-stamp{right:7%;top:22%;width:86px;height:86px;opacity:.73}.intro-stamp:before,.intro-stamp:after{inset:4px}.intro-stamp span{font-size:6px;letter-spacing:1px}.intro-stamp strong{font-size:16px;margin:3px}.intro-stamp b{font-size:6px;margin-top:3px}.controls-note{font-size:8px;max-width:260px;line-height:1.8}.bottom-caption{bottom:102px;left:6%;right:6%;font-size:7px}.bottom-ui{left:6%;right:6%;bottom:max(15px,env(safe-area-inset-bottom));align-items:center}.duel-progress{gap:5px}.progress-dot{width:21px;height:3px}.bottom-hint{display:none}.edition{font-size:7px;letter-spacing:.7px}.edition b{margin-left:3px}.mobile-controls{display:block;position:absolute;left:50%;transform:translateX(-50%);bottom:42px}.draw-button{width:142px;height:52px;border-radius:50%;border:1px solid #f5cd8a;background:#c95337;color:#fff0d9;font:600 14px var(--display);letter-spacing:1.5px;box-shadow:0 0 0 5px #391d14aa,0 5px 20px #12090688;touch-action:manipulation}.draw-button:active{transform:scale(.94);background:#e76541}.duel-prompt{top:32%;min-width:280px}.prompt-text{font-size:clamp(39px,12vw,65px)}.result-card,.ending-card{padding:27px 24px}.result-card h2{font-size:43px}.ending-card h2{font-size:53px}.toast{top:53%;font-size:9px}.bottom-ui:has(~.intro-screen){display:none}}
@media(max-height:650px) and (min-width:701px){.topbar{top:18px}.hud{top:72px}.intro-copy{transform:translateY(-42%)}h1{font-size:78px;margin:14px 0}.intro-desc{margin-bottom:18px}.intro-stamp{top:36%;width:125px;height:125px}.bottom-caption{bottom:82px}.bottom-ui{bottom:17px}}

(() => {
  const canvas = document.getElementById('scene');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = {
    intro: $('introScreen'), hud: $('hud'), prompt: $('duelPrompt'), kicker: $('promptKicker'), promptText: $('promptText'), promptSub: $('promptSub'),
    result: $('resultScreen'), ending: $('endingScreen'), resultEyebrow: $('resultEyebrow'), resultTitle: $('resultTitle'), resultMessage: $('resultMessage'),
    reaction: $('reactionValue'), continue: $('continueButton'), start: $('startButton'), again: $('againButton'), round: $('roundNumber'), roundName: $('roundName'), opponent: $('opponentName'), rank: $('opponentRank'), score: $('scoreValue'), progress: $('duelProgress'),
    hint: $('bottomHint'), draw: $('drawButton'), flash: $('flash'), toast: $('toast'), average: $('averageValue'), sound: $('soundButton')
  };
  const duels = [
    { name: 'CALLE POLVORIENTA', opponent: 'EL FORASTERO', rank: 1, wait: [1700, 3300], window: 1320 },
    { name: 'MESA DEL DIABLO', opponent: 'SILAS “DOS CAÑONES”', rank: 2, wait: [1500, 3100], window: 1120 },
    { name: 'PASO DEL CUERVO', opponent: 'LA VIUDA NEGRA', rank: 2, wait: [1400, 2950], window: 950 },
    { name: 'SANTA CRUZ', opponent: 'HERMANO CAÍN', rank: 3, wait: [1300, 2700], window: 820 },
    { name: 'CIELO ROJO', opponent: 'TOMBSTONE TOM', rank: 3, wait: [1150, 2450], window: 720 },
    { name: 'ÚLTIMA FRONTERA', opponent: 'EL ÁNGEL DE LA MUERTE', rank: 3, wait: [1000, 2250], window: 650 }
  ];
  let width = 0, height = 0, dpr = 1, phase = 'intro', roundIndex = 0, wins = 0, reactionTimes = [], readyAt = 0, deadline = 0, lastShot = 0, startedAt = 0, soundOn = false, audio = null, lastFrame = 0, toastTimer = 0;
  const dust = Array.from({ length: 44 }, (_, i) => ({ x: Math.random(), y: .52 + Math.random() * .48, r: .4 + Math.random() * 2.2, speed: .0007 + Math.random() * .0014, drift: Math.random() * 4, alpha: .08 + Math.random() * .22, seed: i * 19 }));

  function resize() {
    const rect = canvas.getBoundingClientRect();
    width = Math.max(1, rect.width); height = Math.max(1, rect.height); dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(width * dpr); canvas.height = Math.round(height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener('resize', resize); resize();
  const rand = (a, b) => a + Math.random() * (b - a);
  const clamp = (x, a, b) => Math.max(a, Math.min(b, x));

  function path(points, fill, stroke, lineWidth = 1) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath(); if (fill) { ctx.fillStyle = fill; ctx.fill(); } if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth; ctx.stroke(); }
  }
  function polygon(points, color) { path(points, color); }
  function mountain(x, y, w, h, color, seed = 0) {
    const pts = [[x, y + h], [x, y + h * .55]];
    for (let i = 0; i <= 8; i++) {
      const px = x + w * i / 8;
      const peak = Math.sin(i * 2.41 + seed) * .2 + Math.cos(i * 4.7 + seed) * .07;
      pts.push([px, y + h * (.22 + peak + (i % 3) * .07)]);
    }
    pts.push([x + w, y + h]); polygon(pts, color);
  }
  function building(x, y, w, h, front, side, roof, sign, variant = 0) {
    // Deep side wall and shadowed timber façade
    polygon([[x + w * .74, y - h * .04], [x + w, y - h * .13], [x + w, y + h], [x + w * .74, y + h * 1.06]], side);
    polygon([[x, y], [x + w * .74, y - h * .04], [x + w * .74, y + h], [x, y + h * .94]], front);
    polygon([[x - w * .055, y], [x + w * .72, y - h * .16], [x + w * .84, y - h * .05], [x + w * .04, y + h * .1]], roof);
    ctx.fillStyle = '#281813'; ctx.fillRect(x - w * .08, y + h * .24, w * .86, h * .065);
    ctx.fillStyle = '#aa7145'; ctx.fillRect(x - w * .08, y + h * .22, w * .86, h * .025);
    // Porch posts and board seams
    ctx.strokeStyle = '#2c1a14'; ctx.lineWidth = Math.max(1, w * .012);
    for (let i = 1; i < 5; i++) { const xx = x + w * i * .145; ctx.beginPath(); ctx.moveTo(xx, y + h * .29); ctx.lineTo(xx, y + h * .92); ctx.stroke(); }
    ctx.fillStyle = '#1b120f';
    const winY = y + h * .38, winW = w * .15, winH = h * .24;
    for (let i = 0; i < 3; i++) {
      const wx = x + w * (.11 + i * .23); ctx.fillRect(wx, winY, winW, winH);
      ctx.fillStyle = '#b36d3e'; ctx.fillRect(wx - 2, winY - 2, winW + 4, 3); ctx.fillStyle = '#1b120f';
      if (variant === 1) { ctx.strokeStyle = '#9b6946'; ctx.lineWidth = 1; ctx.strokeRect(wx, winY, winW, winH); }
    }
    ctx.fillStyle = '#21140f'; ctx.fillRect(x + w * .47, y + h * .62, w * .18, h * .36);
    // Warm signage
    if (sign) {
      ctx.fillStyle = '#d1a069'; ctx.fillRect(x + w * .1, y + h * .13, w * .6, h * .095);
      ctx.fillStyle = '#4d2a1c'; ctx.textAlign = 'center'; ctx.font = `bold ${Math.max(7, w * .055)}px Georgia`; ctx.fillText(sign, x + w * .4, y + h * .195);
    }
    ctx.fillStyle = '#291911'; ctx.fillRect(x - 4, y + h * .92, w * .83, h * .07);
  }
  function tumbleweed(x, y, scale, t) {
    ctx.save(); ctx.translate(x + Math.sin(t * .0004) * 5, y); ctx.rotate(t * .0007);
    ctx.strokeStyle = '#493022'; ctx.lineWidth = 1.2 * scale; ctx.beginPath();
    for (let i = 0; i < 8; i++) { const a = i * Math.PI / 4; ctx.moveTo(Math.cos(a) * 4 * scale, Math.sin(a) * 4 * scale); ctx.lineTo(Math.cos(a) * 12 * scale, Math.sin(a) * 11 * scale); }
    ctx.arc(0, 0, 8 * scale, 0, Math.PI * 2); ctx.stroke(); ctx.restore();
  }
  function cowboy(x, footY, scale, isPlayer, t, fallen = false, recoil = 0) {
    ctx.save(); ctx.translate(x, footY); ctx.scale(scale, scale);
    if (fallen) { ctx.rotate(isPlayer ? -.26 : .4); ctx.translate(isPlayer ? 3 : -7, 23); }
    const bob = Math.sin(t * .002 + (isPlayer ? .4 : 1.6)) * 1.7;
    const coat = isPlayer ? '#30201a' : '#251714', edge = isPlayer ? '#a9794d' : '#71432e';
    ctx.globalAlpha = .25; ctx.fillStyle = '#170f0c'; ctx.beginPath(); ctx.ellipse(0, 0, 25, 5, 0, 0, Math.PI * 2); ctx.fill(); ctx.globalAlpha = 1;
    if (fallen) {
      // Sideways body and boots
      ctx.fillStyle = '#1c1411'; ctx.beginPath(); ctx.ellipse(0, -16, 29, 11, -.13, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = coat; ctx.fillRect(-18, -28, 36, 16);
      ctx.fillStyle = '#17110f'; ctx.fillRect(13, -17, 20, 6); ctx.fillRect(-30, -15, 17, 6);
      ctx.fillStyle = '#231714'; ctx.beginPath(); ctx.arc(-24, -23, 8, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#120e0c'; ctx.fillRect(-29, -33, 17, 3); ctx.restore(); return;
    }
    // Legs and boots
    ctx.fillStyle = '#211714'; ctx.beginPath(); ctx.moveTo(-12, -43 + bob); ctx.lineTo(-2, -43 + bob); ctx.lineTo(1, -8); ctx.lineTo(-7, -5); ctx.lineTo(-15, -12); ctx.fill();
    ctx.beginPath(); ctx.moveTo(2, -43 + bob); ctx.lineTo(12, -43 + bob); ctx.lineTo(15, -11); ctx.lineTo(8, -5); ctx.lineTo(1, -10); ctx.fill();
    ctx.fillStyle = '#130f0d'; ctx.fillRect(-17, -8, 14, 5); ctx.fillRect(5, -8, 14, 5);
    // Long coat with split tails
    polygon([[-14, -77 + bob], [13, -77 + bob], [17, -45], [13, -31], [5, -44], [-2, -32], [-8, -45], [-16, -35], [-19, -48]], coat);
    ctx.strokeStyle = edge; ctx.lineWidth = 1.2; ctx.beginPath(); ctx.moveTo(-14, -72 + bob); ctx.lineTo(-11, -47); ctx.moveTo(11, -72 + bob); ctx.lineTo(8, -49); ctx.stroke();
    // Neck + head
    ctx.fillStyle = '#a86d49'; ctx.fillRect(-5, -87 + bob, 10, 12);
    ctx.fillStyle = '#bd8259'; ctx.beginPath(); ctx.ellipse(0, -97 + bob, 10, 12, 0, 0, Math.PI * 2); ctx.fill();
    // Hair, hat brim, crown
    ctx.fillStyle = '#241813'; ctx.beginPath(); ctx.arc(0, -101 + bob, 10, Math.PI, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#201511'; ctx.beginPath(); ctx.ellipse(0, -108 + bob, 19, 3, -.04, 0, Math.PI * 2); ctx.fill();
    ctx.fillRect(-10, -119 + bob, 20, 12); ctx.fillStyle = '#875532'; ctx.fillRect(-10, -111 + bob, 20, 2);
    // Bandana
    ctx.fillStyle = isPlayer ? '#b54b33' : '#ded0b8'; polygon([[-8, -82 + bob], [8, -82 + bob], [6, -76 + bob], [0, -73 + bob], [-6, -77 + bob]], ctx.fillStyle);
    // Gun hand and revolver: poised at hip before draw, raised after
    const raising = recoil > 0 ? Math.min(1, recoil) : (phase === 'armed' ? 1 : 0);
    const armAngle = isPlayer ? -.15 - raising * .82 : Math.PI + .15 + raising * .82;
    const sx = isPlayer ? 11 : -11, sy = -75 + bob;
    const ex = sx + Math.cos(armAngle) * 22, ey = sy + Math.sin(armAngle) * 22;
    ctx.strokeStyle = coat; ctx.lineWidth = 7; ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke();
    ctx.fillStyle = '#ae7954'; ctx.beginPath(); ctx.arc(ex, ey, 3.5, 0, Math.PI * 2); ctx.fill();
    if (raising > .12 || (isPlayer && phase === 'armed')) {
      const dir = isPlayer ? 1 : -1; ctx.save(); ctx.translate(ex, ey); ctx.rotate(isPlayer ? -.12 : Math.PI + .12);
      ctx.fillStyle = '#231915'; ctx.fillRect(0, -2, 13 * dir, 4); ctx.fillRect(4 * dir, 1, 3 * dir, 7); ctx.fillStyle = '#a98254'; ctx.fillRect(9 * dir, -1, 5 * dir, 2); ctx.restore();
    }
    // Belt and holster
    ctx.strokeStyle = '#a67a4d'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(-12, -48); ctx.lineTo(13, -48); ctx.stroke();
    ctx.fillStyle = '#9d7046'; ctx.fillRect(isPlayer ? 5 : -8, -49, 5, 13);
    ctx.restore();
  }
  function drawScene(t) {
    const w = width, h = height, sx = w / 1280, sy = h / 720;
    ctx.setTransform(dpr * sx, 0, 0, dpr * sy, 0, 0);
    // Sunset sky and distant mesa country
