node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true, executablePath:'/home/runner/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome', args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1440,height:900}}); const errors=[]; page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:3002'); await page.screenshot({path:'screenshots/duel-intro-test.png'});
 await page.locator('#startButton').click();
 const rounds=[];
 for(let i=1;i<=6;i++){
   await page.waitForFunction(()=>document.querySelector('#duelPrompt').classList.contains('ready'),null,{timeout:10000});
   const title=await page.locator('#roundName').textContent();
   await page.keyboard.press('Space');
   await page.waitForFunction(()=>!document.querySelector('#resultScreen').hidden,{timeout:3000});
   const result=await page.locator('#resultTitle').textContent(); rounds.push([i,title,result]);
   if(i<6) await page.locator('#continueButton').click();
   else await page.locator('#continueButton').click();
 }
 await page.waitForFunction(()=>!document.querySelector('#endingScreen').hidden);
 console.log(JSON.stringify({rounds,ending:await page.locator('#averageValue').textContent(),errors},null,2));
 await page.screenshot({path:'screenshots/duel-ending-test.png'});
 const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});
 await mobile.goto('http://localhost:3002'); await mobile.screenshot({path:'screenshots/duel-mobile-test.png'});
 await mobile.locator('#startButton').tap(); await mobile.waitForFunction(()=>!document.querySelector('#hud').hidden);
 await mobile.waitForFunction(()=>document.querySelector('#duelPrompt').classList.contains('ready'),null,{timeout:10000});
 await mobile.locator('#drawButton').tap(); await mobile.waitForFunction(()=>!document.querySelector('#resultScreen').hidden);
 console.log('mobile result',await mobile.locator('#resultTitle').textContent()); await mobile.screenshot({path:'screenshots/duel-mobile-result-test.png'});
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
NODE

